def theory_review(topic):
    example, detail, method, pitfall, ready, related, minutes = REVIEWS[topic]
    return {
        "minutes": minutes,
        "explanation": [
            {"title": tr("Namunada nima bor", "Что есть в примере", "Inside the example"), "text": example},
            {"title": tr("Qanday tushunamiz", "Как это понять", "Understand what you hear"), "text": detail},
            {"title": tr("O‘zingiz sinab ko‘ring", "Попробуйте сами", "Try it yourself"), "text": method},
            {"title": tr("Chalkashtirmang", "Не перепутайте", "Keep the distinction clear"), "text": pitfall},
        ],
        "steps": [
            {"title": tr("Misolni tinglang", "Послушайте пример", "Hear the example"), "instruction": example},
            {"title": tr("Farqni tekshiring", "Проверьте различие", "Check the difference"), "instruction": method},
            {"title": tr("O‘z so‘zingiz bilan ayting", "Объясните своими словами", "Explain it in your words"), "instruction": ready},
        ],
        "ready_when": ready,
        "related_ids": [f"theory:{key}" for key in related],
    }


def challenge_preparation(topic):
    """Keep the relevant concept beside the task, before any answer is checked."""
    if topic == "intervals":
        return tr(
            "Interval — ikki tovush orasidagi masofa. Tersiya uchta nota nomini qamrab oladi: C–D–E, demak chekka tovushlar C va E. Katta tersiya 4 yarim ton: C→C♯→D→D♯→E — to‘rtta qo‘shni klavish qadami; boshlang‘ich C qadam deb sanalmaydi. Kichik tersiya 3 yarim ton: C–E♭. Kvarta C–F — 5, kvinta C–G — 7 yarim ton. C4 — o‘rta do, raqam esa oktavani bildiradi.",
            "Интервал — расстояние между двумя звуками. Терция охватывает три названия: C–D–E, её крайние звуки C и E. Большая терция — 4 полутона: C→C♯→D→D♯→E, четыре перехода на соседнюю клавишу; исходный C не считается шагом. Малая терция — 3 полутона: C–E♭. Кварта C–F — 5, квинта C–G — 7 полутонов. C4 — среднее до; цифра обозначает октаву.",
            "An interval is the distance between two tones. A third spans three note names: C–D–E, so its endpoints are C and E. A major third is four semitones: C→C♯→D→D♯→E, four moves to adjacent keys; the starting C is not a step. A minor third is three semitones: C–E♭. A fourth C–F is five and a fifth C–G seven semitones. C4 is middle C; the number identifies its octave.",
        )
    return REVIEWS[topic][1]
